func NewEntry() *Entry {
	e := &Entry{Wrapping: fyne.TextTruncate}
	e.ExtendBaseWidget(e)
	return e
}

// NewEntryWithData returns an Entry widget connected to the specified data source.
//
// Since: 2.0
func NewEntryWithData(data binding.String) *Entry {
	entry := NewEntry()
	entry.Bind(data)

	return entry
}

// NewMultiLineEntry creates a new entry that allows multiple lines
func NewMultiLineEntry() *Entry {
	e := &Entry{MultiLine: true, Wrapping: fyne.TextTruncate}
	e.ExtendBaseWidget(e)
	return e
}

// NewPasswordEntry creates a new entry password widget
func NewPasswordEntry() *Entry {
	e := &Entry{Password: true, Wrapping: fyne.TextTruncate}
	e.ExtendBaseWidget(e)
	e.ActionItem = newPasswordRevealer(e)
	return e
}

// AcceptsTab returns if Entry accepts the Tab key or not.
//
// Implements: fyne.Tabbable
//
// Since: 2.1
func (e *Entry) AcceptsTab() bool {
	return e.MultiLine
}

// Bind connects the specified data source to this Entry.
// The current value will be displayed and any changes in the data will cause the widget to update.
// User interactions with this Entry will set the value into the data source.
//
// Since: 2.0
func (e *Entry) Bind(data binding.String) {
	e.binder.SetCallback(e.updateFromData)
	e.binder.Bind(data)

	e.Validator = func(string) error {
		return e.conversionError
	}

	e.OnChanged = func(_ string) {
		e.binder.CallWithData(e.writeData)
		e.Validate()

package validation

import "fyne.io/fyne/v2"

// NewAllStrings creates a validator combinator that runs all provided validators in order.
// It returns a StringValidator that validates the input against all validators and returns
// the first error encountered. If all validators pass, it returns nil.
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}

package desktop

import "fyne.io/fyne/v2"

// App interface extends fyne.App with desktop-specific functionality.
// This interface defines additional methods for desktop platforms such as
// system tray integration.
//
// Since: 2.2
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the system tray menu for the application.
	// This allows the application to add a menu to the system tray/notification area.
	// Pass nil to remove the system tray menu.
	//
	// Since: 2.2
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the system tray icon for the application.
	// This allows the application to display an icon in the system tray/notification area.
	// Pass nil to remove the system tray icon.
	//
	// Since: 2.2
	SetSystemTrayIcon(icon fyne.Resource)
}

