package widget

import (
	"image/color"
	"net/url"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/canvas"
	"fyne.io/fyne/v2/driver/desktop"
	"fyne.io/fyne/v2/theme"
)

var _ fyne.Focusable = (*Hyperlink)(nil)
var _ fyne.Widget = (*Hyperlink)(nil)

// Hyperlink widget is a text component with appropriate padding and layout.
// When clicked, the default web browser should open with a URL
type Hyperlink struct {
	BaseWidget
	Text      string
	URL       *url.URL
	Alignment fyne.TextAlign // The alignment of the Text
	Wrapping  fyne.TextWrap  // The wrapping of the Text
	TextStyle fyne.TextStyle // The style of the hyperlink text

	// OnTapped is called when the hyperlink is tapped/clicked.
	// This is triggered in addition to the default URL opening behavior.
	//
	// Since: 2.2
	OnTapped func() `json:"-"`

	focused, hovered bool
	provider         *RichText
}

// NewHyperlink creates a new hyperlink widget with the set text content
func NewHyperlink(text string, url *url.URL) *Hyperlink {
	return NewHyperlinkWithStyle(text, url, fyne.TextAlignLeading, fyne.TextStyle{})
}

// NewHyperlinkWithStyle creates a new hyperlink widget with the set text content
func NewHyperlinkWithStyle(text string, url *url.URL, alignment fyne.TextAlign, style fyne.TextStyle) *Hyperlink {
	hl := &Hyperlink{
		Text:      text,
		URL:       url,
		Alignment: alignment,
		TextStyle: style,
	}

	return hl
}

// CreateRenderer is a private method to Fyne which links this widget to its renderer
func (hl *Hyperlink) CreateRenderer() fyne.WidgetRenderer {
	hl.ExtendBaseWidget(hl)
	hl.provider = NewRichTextWithText(hl.Text)
	hl.provider.ExtendBaseWidget(hl.provider)
	hl.syncSegments()

	focus := canvas.NewRectangle(color.Transparent)
	focus.StrokeColor = theme.FocusColor()
	focus.StrokeWidth = 2
	focus.Hide()
	under := canvas.NewRectangle(theme.PrimaryColor())
	under.Hide()
	return &hyperlinkRenderer{hl: hl, objects: []fyne.CanvasObject{hl.provider, focus, under}, focus: focus, under: under}
}

// Cursor returns the cursor type of this widget
func (hl *Hyperlink) Cursor() desktop.Cursor {
	return desktop.PointerCursor
}

// FocusGained is a hook called by the focus handling logic after this object gained the focus.
func (hl *Hyperlink) FocusGained() {
	hl.focused = true
	hl.BaseWidget.Refresh()
}

// FocusLost is a hook called by the focus handling logic after this object lost the focus.
func (hl *Hyperlink) FocusLost() {
	hl.focused = false
	hl.BaseWidget.Refresh()
}

// MouseIn is a hook that is called if the mouse pointer enters the element.
func (hl *Hyperlink) MouseIn(*desktop.MouseEvent) {
	hl.hovered = true
	hl.BaseWidget.Refresh()
}

// MouseMoved is a hook that is called if the mouse pointer moved over the element.
func (hl *Hyperlink) MouseMoved(*desktop.MouseEvent) {
}

// MouseOut is a hook that is called if the mouse pointer leaves the element.
func (hl *Hyperlink) MouseOut() {
	hl.hovered = false
	hl.BaseWidget.Refresh()
}

package widget

import (
	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/canvas"
	"fyne.io/fyne/v2/internal/widget"
	"fyne.io/fyne/v2/layout"
	"fyne.io/fyne/v2/theme"
)

// ToolbarItem represents any interface element that can be added to a toolbar
type ToolbarItem interface {
	ToolbarObject() fyne.CanvasObject
}

// ToolbarAction is push button style of ToolbarItem
type ToolbarAction struct {
	Icon        fyne.Resource
	OnActivated func() `json:"-"`
}

// ToolbarObject gets a button to render this ToolbarAction
func (t *ToolbarAction) ToolbarObject() fyne.CanvasObject {
	button := NewButtonWithIcon("", t.Icon, t.OnActivated)
	button.Importance = LowImportance

	return button
}

// SetIcon updates the icon for this ToolbarAction and refreshes its display.
//
// Since: 2.2
func (t *ToolbarAction) SetIcon(icon fyne.Resource) {
	t.Icon = icon
}

// NewToolbarAction returns a new push button style ToolbarItem
func NewToolbarAction(icon fyne.Resource, onActivated func()) *ToolbarAction {
	return &ToolbarAction{icon, onActivated}
}

// ToolbarSpacer is a blank, stretchable space for a toolbar.
// This is typically used to assist layout if you wish some left and some right aligned items.
// Space will be split evebly amongst all the spacers on a toolbar.
type ToolbarSpacer struct {
}

// ToolbarObject gets the actual spacer object for this ToolbarSpacer
func (t *ToolbarSpacer) ToolbarObject() fyne.CanvasObject {
	return layout.NewSpacer()
}

// NewToolbarSpacer returns a new spacer item for a Toolbar to assist with ToolbarItem alignment
func NewToolbarSpacer() *ToolbarSpacer {
	return &ToolbarSpacer{}
}

// ToolbarSeparator is a thin, visible divide that can be added to a Toolbar.
// This is typically used to assist visual grouping of ToolbarItems.
type ToolbarSeparator struct {
}

// ToolbarObject gets the visible line object for this ToolbarSeparator
func (t *ToolbarSeparator) ToolbarObject() fyne.CanvasObject {
	return canvas.NewRectangle(theme.ForegroundColor())
}

// NewToolbarSeparator returns a new separator item for a Toolbar to assist with ToolbarItem grouping
func NewToolbarSeparator() *ToolbarSeparator {
	return &ToolbarSeparator{}
}

// Toolbar widget creates a horizontal list of tool buttons
type Toolbar struct {
	BaseWidget
	Items []ToolbarItem
}

// CreateRenderer is a private method to Fyne which links this widget to its renderer
func (t *Toolbar) CreateRenderer() fyne.WidgetRenderer {
	t.ExtendBaseWidget(t)
	r := &toolbarRenderer{toolbar: t, layout: layout.NewHBoxLayout()}
	r.resetObjects()
	return r
}

// Append a new ToolbarItem to the end of this Toolbar
func (t *Toolbar) Append(item ToolbarItem) {
	t.Items = append(t.Items, item)
	t.Refresh()
}

// Prepend a new ToolbarItem to the start of this Toolbar
func (t *Toolbar) Prepend(item ToolbarItem) {
	t.Items = append([]ToolbarItem{item}, t.Items...)
	t.Refresh()
}

// MinSize returns the size that this widget should not shrink below
func (t *Toolbar) MinSize() fyne.Size {
	t.ExtendBaseWidget(t)
	return t.BaseWidget.MinSize()
}

// NewToolbar creates a new toolbar widget.
func NewToolbar(items ...ToolbarItem) *Toolbar {
	t := &Toolbar{Items: items}
	t.ExtendBaseWidget(t)

	t.Refresh()
	return t
}

type toolbarRenderer struct {
	widget.BaseRenderer
	layout  fyne.Layout
	items   []fyne.CanvasObject
	toolbar *Toolbar
}

func (r *toolbarRenderer) MinSize() fyne.Size {
	return r.layout.MinSize(r.items)
}

func (r *toolbarRenderer) Layout(size fyne.Size) {
	r.layout.Layout(r.items, size)
}

func (r *toolbarRenderer) Refresh() {
	r.resetObjects()
	for i, item := range r.toolbar.Items {
		if _, ok := item.(*ToolbarSeparator); ok {
			rect := r.items[i].(*canvas.Rectangle)
			rect.FillColor = theme.ForegroundColor()
		}
	}

	canvas.Refresh(r.toolbar)
}

func (r *toolbarRenderer) resetObjects() {
	r.items = make([]fyne.CanvasObject, 0, len(r.toolbar.Items))
	for _, item := range r.toolbar.Items {
		r.items = append(r.items, item.ToolbarObject())
	}
	r.SetObjects(r.items)
}

package binding

import (
	"fmt"
	"sync"
)

// sprintfBinding is a String binding that formats multiple data items using a format string.
type sprintfBinding struct {
	base
	format  string
	sources []DataItem

	lock sync.RWMutex
}

// NewSprintf creates a new String binding that formats its value using fmt.Sprintf.
// The format string and data sources are provided, and the binding updates whenever
// any source data changes.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.2
func NewSprintf(format string, sources ...DataItem) String {
	b := &sprintfBinding{
		format:  format,
		sources: sources,
	}

	// Listen to all source data items
	for _, source := range sources {
		source.AddListener(b)
	}

	return b
}

// DataChanged is called when any of the source data items change.
// It triggers a refresh of the formatted string.
func (b *sprintfBinding) DataChanged() {
	b.trigger()
}

// Get returns the current formatted string value.
func (b *sprintfBinding) Get() (string, error) {
	b.lock.RLock()
	defer b.lock.RUnlock()

	// Extract values from all sources
	values := make([]interface{}, len(b.sources))
	for i, source := range b.sources {
		switch s := source.(type) {
		case String:
			if val, err := s.Get(); err == nil {
				values[i] = val
			} else {
				return "", err
			}
		case Int:
			if val, err := s.Get(); err == nil {
				values[i] = val
			} else {
				return "", err
			}
		case Float:
			if val, err := s.Get(); err == nil {
				values[i] = val
			} else {
				return "", err
			}
		case Bool:
			if val, err := s.Get(); err == nil {
				values[i] = val
			} else {
				return "", err
			}
		case Untyped:
			if val, err := s.Get(); err == nil {
				values[i] = val
			} else {
				return "", err
			}
		default:
			// For any other type, try Untyped interface
			if u, ok := source.(Untyped); ok {
				if val, err := u.Get(); err == nil {
					values[i] = val
				} else {
					return "", err
				}
			} else {
				values[i] = nil
			}
		}
	}

	return fmt.Sprintf(b.format, values...), nil
}

// Set parses the string back using fmt.Sscanf and sets each source binding to the parsed value.
// The format string is used to extract values which are then set on the corresponding source bindings.
//
// Since: 2.2
func (b *sprintfBinding) Set(str string) error {
	b.lock.Lock()
	defer b.lock.Unlock()

	// Create destination pointers for Sscanf based on source types
	values := make([]interface{}, len(b.sources))
	for i, source := range b.sources {
		switch source.(type) {
		case String:
			var s string
			values[i] = &s
		case Int:
			var n int
			values[i] = &n
		case Float:
			var f float64
			values[i] = &f
		case Bool:
			var bo bool
			values[i] = &bo
		default:
			// For other types, use interface{}
			var v interface{}
			values[i] = &v
		}
	}

	// Parse the string using the format
	n, err := fmt.Sscanf(str, b.format, values...)
	if err != nil {
		return fmt.Errorf("failed to parse sprintf binding value: %w", err)
	}
	if n != len(b.sources) {
		return fmt.Errorf("parsed %d values but expected %d", n, len(b.sources))
	}

	// Set the parsed values back to sources
	for i, source := range b.sources {
		switch s := source.(type) {
		case String:
			if strVal, ok := values[i].(*string); ok {
				if err := s.Set(*strVal); err != nil {
					return err
				}
			}
		case Int:
			if intVal, ok := values[i].(*int); ok {
				if err := s.Set(*intVal); err != nil {
					return err
				}
			}
		case Float:
			if floatVal, ok := values[i].(*float64); ok {
				if err := s.Set(*floatVal); err != nil {
					return err
				}
			}
		case Bool:
			if boolVal, ok := values[i].(*bool); ok {
				if err := s.Set(*boolVal); err != nil {
					return err
				}
			}
		case Untyped:
			if untypedVal, ok := values[i].(*interface{}); ok {
				if err := s.Set(*untypedVal); err != nil {
					return err
				}
			}
		}
	}

	return nil
}

// stringToStringWithFormat is a String binding that applies a format transformation to another String binding.
type stringToStringWithFormat struct {
	base
	format string
	source String

	lock sync.RWMutex
}

// StringToStringWithFormat creates a new String binding that formats another String binding value
// using the provided format string. The format string should contain exactly one %s placeholder.
//
// Example:
//   name := binding.NewString()
//   name.Set("Alice")
//   greeting := binding.StringToStringWithFormat(name, "Hello, %s!")
//   // greeting.Get() returns "Hello, Alice!"
//
// Since: 2.2

